True def transform(grid):
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (2, 8):
                stem = 3 if value == 2 else 2
                for d in range(1, stem + 2):
                    rr = r - d
                    if rr < 0:
                        break
                    out[rr][c] = value if d == stem + 1 else 1
    return out
